import { expect, type Page } from "@playwright/test";

// Set storage in the current origin instead of accumulating init scripts whose
// execution order is undefined when a matrix navigates through several themes.
export async function setThemePreferences(
  page: Page,
  appearance: string,
  mode: string,
) {
  if (page.url() === "about:blank") await page.goto("/privacy");
  await page.evaluate(
    ({ appearance, mode }) => {
      localStorage.setItem("mailloop-appearance", appearance);
      localStorage.setItem("mailloop-theme", mode);
    },
    { appearance, mode },
  );
}

export async function settleTheme(page: Page) {
  await expect(page.locator("html")).not.toHaveAttribute(
    "data-appearance-transition",
  );
  await expect(page.locator("html")).not.toHaveAttribute("data-theme-reveal");
  await page.evaluate(() => document.fonts.ready);
  await expect
    .poll(() =>
      page.evaluate(() =>
        document
          .getAnimations()
          .filter(
            (animation) =>
              animation.playState === "running" &&
              Number.isFinite(
                animation.effect?.getComputedTiming().endTime ?? Infinity,
              ),
          )
          .map((animation) =>
            animation instanceof CSSTransition
              ? animation.transitionProperty
              : animation instanceof CSSAnimation
                ? animation.animationName
                : "animation",
          ),
      ),
    )
    .toEqual([]);
  await page.evaluate(
    () =>
      new Promise<void>((resolve) =>
        requestAnimationFrame(() => requestAnimationFrame(() => resolve())),
      ),
  );
}
